<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $reference
 * @property string $provider
 * @property string $currency
 * @property int $payouts_count
 * @property int $total_amount
 * @property string $status
 * @property string $created_by
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class PayoutBatch extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'pob';

    protected $fillable = [
        'reference', 'provider', 'currency', 'payouts_count', 'total_amount', 'status', 'created_by',
    ];

    /** @return HasMany<Payout, $this> */
    public function payouts(): HasMany
    {
        return $this->hasMany(Payout::class, 'batch_id');
    }
}
